/**
 * getTaskList is a function that returns a Promise that resolves to an array of tasks.
 *
 * For example:
 * ```json
 * [
 *   {
 *     "id": 1,
 *     "key": "ISSUE-1",
 *     "link": "/issues/1",
 *     "description": "Lorem ipsum dolor sit amet consectetur adipiscing elit dedo eiusmod tempor incididunt ut labore et dolore magna aliqua.",
 *     "priority": 0
 *   }
 * ]
 * ```
 * @param {number} [start=1] - The start index of the tasks to return.
 * @returns {Promise<Array<{id: number, key: string, link: string, description: string, priority: number}>> | null>} - A Promise that resolves to an array of tasks, or null if there are no more tasks.
 */
export function getTaskList(t = 1) { const o = "Lorem ipsum dolor sit amet consectetur adipiscing elit dedo eiusmod tempor incididunt ut labore et dolore magna aliqua".split(" "); const e = 15; const i = 5; return new Promise(n => { setTimeout(() => { const s = []; if (t >= e) { n(null); return } for (let n = t; n < Math.min(t + i, e); n++) { const t = 3; const e = o.length; const i = Math.min(e, Math.floor(Math.random() * e) + t); const r = Math.floor(Math.random() * (e - i + 1)); let a = o.slice(r, r + i); let l = a.join(" ") + "."; l = l.charAt(0).toUpperCase() + l.slice(1); s.push({ id: n, key: `ISSUE-${n}`, link: `/issues/${n}`, description: l, priority: Math.floor(Math.random() * 3) }) } n(s) }, 500 + Math.random() * 500) }) }
